-- Generated from the original .mail files. Existing database edits are never overwritten.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
DECLARE @lockResult int;
EXEC @lockResult = sys.sp_getapplock @Resource = N'EIS_MAIL_TEMPLATE_INSTALL', @LockMode = 'Exclusive', @LockOwner = 'Transaction', @LockTimeout = 30000;
IF @lockResult < 0 THROW 51000, 'Could not lock mail template installation', 1;
IF OBJECT_ID(N'dbo.MAIL_TEMPLATE', N'U') IS NULL
BEGIN
    CREATE TABLE dbo.MAIL_TEMPLATE (
        TemplateKey nvarchar(100) NOT NULL CONSTRAINT PK_MAIL_TEMPLATE PRIMARY KEY,
        Name nvarchar(200) NOT NULL,
        Subject nvarchar(500) NOT NULL,
        BodyHtml nvarchar(max) NOT NULL,
        ContentType nvarchar(100) NOT NULL,
        SourceFileName nvarchar(200) NOT NULL,
        PlaceholdersJson nvarchar(max) NOT NULL,
        Revision int NOT NULL CONSTRAINT DF_MAIL_TEMPLATE_Revision DEFAULT 1,
        CreatedAt datetime2 NOT NULL CONSTRAINT DF_MAIL_TEMPLATE_CreatedAt DEFAULT SYSUTCDATETIME(),
        UpdatedAt datetime2 NOT NULL CONSTRAINT DF_MAIL_TEMPLATE_UpdatedAt DEFAULT SYSUTCDATETIME(),
        UpdatedByUserId int NULL
    );
END;

IF NOT EXISTS (SELECT 1 FROM dbo.MAIL_TEMPLATE WHERE TemplateKey = N'CUSTOMER_CONFIRMATION')
INSERT INTO dbo.MAIL_TEMPLATE (TemplateKey, Name, Subject, BodyHtml, ContentType, SourceFileName, PlaceholdersJson) VALUES (
CAST(N'CUSTOMER_CONFIRMATION' AS nvarchar(max)),
CAST(N'Customer Confirmation' AS nvarchar(max)),
CAST(N'Confirm your account setup for {{applicationName}}' AS nvarchar(max)),
CAST(N'<!doctype html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <title>Confirm your account setup</title>
</head>
<body style="margin:0;padding:0;background-color:#f4f6f8;font-family:Arial,Helvetica,sans-serif;color:#1f2933;">
<table data-eis-banner="true" role="presentation" width="640" cellspacing="0" cellpadding="0" style="width:100%;max-width:640px;margin:24px auto 0;background-color:#073f34;background-image:linear-gradient(180deg,#073f34 0%,#052f27 100%);border-radius:12px;color:#ffffff;font-family:Arial,Helvetica,sans-serif;">
<tr><td style="width:120px;padding:18px 12px;vertical-align:middle;"><img src="data:image/png;base64,' AS nvarchar(max)) + N'' + N'' + N'' + N'' + N'' + N'" alt="EIS - Engineering in Systems" width="110" height="26" style="display:block;border:0;"></td><td style="padding:18px 8px;text-align:center;color:#ffffff;font-size:18px;font-weight:bold;white-space:nowrap;">Confirm your account setup</td><td style="width:120px;padding:18px 12px;"></td></tr>
</table>

<table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="background-color:#f4f6f8;margin:0;padding:24px 0;">
    <tr>
        <td align="center">
            <table role="presentation" width="640" cellspacing="0" cellpadding="0" style="width:640px;max-width:100%;background-color:#ffffff;border-radius:8px;overflow:hidden;border:1px solid #d9e2ec;">
                

                <tr>
                    <td style="padding:32px;">
                        <p style="margin:0 0 16px 0;font-size:16px;line-height:1.5;">
                            Hello {{customerContactName}},
                        </p>

                        <p style="margin:0 0 16px 0;font-size:16px;line-height:1.5;">
                            Thank you for creating an account for <strong>{{customerName}}</strong> with {{applicationName}}.
                        </p>

                        <p style="margin:0 0 20px 0;font-size:16px;line-height:1.5;">
                            Before we can activate your trial period, you need to confirm the account setup.
                            Once confirmed, your <strong>{{trialDays}}-day trial period</strong> will begin.
                        </p>

                        <table role="presentation" cellspacing="0" cellpadding="0" style="margin:24px 0;">
                            <tr>
                                <td style="border-radius:6px;background-color:#0b69a3;">
                                    <a href="{{confirmationLink}}"
                                       style="display:inline-block;padding:14px 22px;font-size:16px;line-height:1.2;color:#ffffff;text' + N'-decoration:none;font-weight:700;border-radius:6px;">
                                        Confirm account setup
                                    </a>
                                </td>
                            </tr>
                        </table>

                        <p style="margin:0 0 16px 0;font-size:14px;line-height:1.5;color:#52606d;">
                            If the button does not work, copy and paste this link into your browser:
                        </p>

                        <p style="margin:0 0 20px 0;font-size:14px;line-height:1.5;word-break:break-all;">
                            <a href="{{confirmationLink}}" style="color:#0b69a3;text-decoration:underline;">{{confirmationLink}}</a>
                        </p>

                        <p style="margin:0 0 16px 0;font-size:14px;line-height:1.5;color:#52606d;">
                            This confirmation link expires at: <strong>{{confirmationExpiresAt}}</strong>.
                        </p>

                        <p style="margin:20px 0 0 0;font-size:14px;line-height:1.5;color:#52606d;">
                            If you did not create this account, you can safely ignore this email.
                        </p>
                    </td>
                </tr>

                <tr>
                    <td style="padding:20px 32px;background-color:#f8fafc;border-top:1px solid #d9e2ec;">
                        <p style="margin:0;font-size:12px;line-height:1.5;color:#7b8794;">
                            This email was sent automatically by {{applicationName}}. Please do not reply to this email.
                        </p>
                        <p style="margin:8px 0 0 0;font-size:12px;line-height:1.5;color:#7b8794;">
                            Customer ID: {{customerId}} · Workflow ID: {{workflowId}}
                        </p>
                    </td>
                </tr>
            </table>
        </td>
    </tr>
</table>
</body>
</html>',
CAST(N'text/html; charset=UTF-8' AS nvarchar(max)),
CAST(N'customer-confirmation.mail' AS nvarchar(max)),
CAST(N'["applicationName","confirmationExpiresAt","confirmationLink","customerContactName","customerId","customerName","trialDays","workflowId"]' AS nvarchar(max)));

