<tr><td style="width:120px;padding:18px 12px;vertical-align:middle;"><img src="data:image/png;base64,' AS nvarchar(max)) + N'' + N'' + N'' + N'' + N'' + N'" alt="EIS - Engineering in Systems" width="110" height="26" style="display:block;border:0;"></td><td style="padding:18px 8px;text-align:center;color:#ffffff;font-size:18px;font-weight:bold;white-space:nowrap;">Welcome to BEPA EIS</td><td style="width:120px;padding:18px 12px;"></td></tr>
